-- =============================================================================
-- cargas/planeacion_compras_inicial.sql   (requiere 0059, 0060 y 0061)
-- Carga inicial de PLANEACION DE COMPRAS:
--  * 17 proveedores (hojas de PRODUCTOS_2026_ACTUALIZADO.xlsx) con sus dias de entrega y reglas.
--  * Articulos de cada proveedor con empaque, CBM y precio.
--  * Corte de existencias de Microsip al 18/11/2026 (kardex del Almacen general).
--  * Historial de venta por mes desde dic 2024 (kardex).
--  * OCs abiertas del Excel agrupadas por orden. Las de China se toman como recibidas completas solo si
--    la mayoria de sus renglones ya entro en Microsip; topglove puede recibir por renglon.
-- Se puede volver a correr: actualiza proveedores, articulos, existencias e historial; las OCs que ya
-- existen no se tocan (para no perder lo que hayas cambiado en el portal).
-- Como aplicarlo: pega este archivo COMPLETO en SQL Editor y presiona Run.
-- =============================================================================
begin;

-- Nombres de proveedor en mayusculas (si ya estaban cargados con el nombre de la hoja).
update public.plan_proveedores set nombre='TOPGLOVE (GD CARE)' where nombre='topglove(GD Care)' and not exists (select 1 from public.plan_proveedores where nombre='TOPGLOVE (GD CARE)');
update public.plan_proveedores set nombre='CHENGLI' where nombre='chengli 1año' and not exists (select 1 from public.plan_proveedores where nombre='CHENGLI');
update public.plan_proveedores set nombre='DALLAS' where nombre='dallas' and not exists (select 1 from public.plan_proveedores where nombre='DALLAS');
update public.plan_proveedores set nombre='LIFEGUARD' where nombre='lifeguard' and not exists (select 1 from public.plan_proveedores where nombre='LIFEGUARD');
update public.plan_proveedores set nombre='PURITAN' where nombre='puritan' and not exists (select 1 from public.plan_proveedores where nombre='PURITAN');
update public.plan_proveedores set nombre='LTS' where nombre='lts' and not exists (select 1 from public.plan_proveedores where nombre='LTS');
update public.plan_proveedores set nombre='SDI' where nombre='sdi' and not exists (select 1 from public.plan_proveedores where nombre='SDI');
update public.plan_proveedores set nombre='NEW PIG' where nombre='new pig' and not exists (select 1 from public.plan_proveedores where nombre='NEW PIG');
update public.plan_proveedores set nombre='MSC' where nombre='msc' and not exists (select 1 from public.plan_proveedores where nombre='MSC');
update public.plan_proveedores set nombre='AMBIDERM' where nombre='ambiderm' and not exists (select 1 from public.plan_proveedores where nombre='AMBIDERM');

on conflict (clave) do update set proveedor_id=excluded.proveedor_id, nombre=excluded.nombre, um=excluded.um, codigo_proveedor=coalesce(public.plan_articulos.codigo_proveedor, excluded.codigo_proveedor), descripcion_proveedor=coalesce(public.plan_articulos.descripcion_proveedor, excluded.descripcion_proveedor), empaque=excluded.empaque, cbm_empaque=excluded.cbm_empaque, precio=excluded.precio, pedido_tipico=excluded.pedido_tipico, activo=true;
-- Lo que ya no esta en el Excel (por ejemplo lo de abajo de la franja amarilla en RUNKUN) se desactiva.
update public.plan_articulos set activo=false where clave not in ('ESC-PCRPAD','ESC-A2910','ESC-A806WC-HOSP','ESC-WC43','ESC-WV-95','ESC-WFS5014Y','ESC-WMFAL-88','ESC-W900-P','ESC-WFS5014B','ESC-WFS5014S','ESC-GLBP1-L','ESC-GLBP1-M','ESC-GLBP1-S','ESC-GLPFGG-L','ESC-GLPFGG-M','ESC-GLPFGG-S','ESC-GLPFGG-XL','ESC-GLPFGG-XS','ESC-GNPF8-2XL','ESC-GNPF8-L','ESC-GNPF8-M','ESC-GNPF8-S','ESC-GNPF8-XL','ESC-GNPFGG5-L','ESC-GNPFGG5-M','ESC-GNPFGG5-S','ESC-GNPFGGBK-L','ESC-GNPFGGBK-M','ESC-GNPFGGBK-S','ESC-GNPFGGBK-XL','ESC-GNPFON6-L','ESC-GNPFON6-M','ESC-GNPFON6-S','ESC-GNPFON6-XL','ESC-GNPFSBK-L','ESC-GNPFSBK-M','ESC-GNPFSBK-S','ESC-GNPFSBK-XL','ESC-GNPFSP-L','ESC-GNPFSP-M','ESC-GNPFSP-S','ESC-GNPFSP-XL','ESC-SPAT235','ESC-GNPFLG-M','ESC-GNPFLG-S','ESC-GNPFLG-L','ESC-DMPE-2442','ESC-DMPE-2846','ESC-GNPFL8-S','ESC-GNPFL8-M','ESC-GNPFL8-L','ESC-GNPFL8-XL','ESC-TMFVA1-00546','ESC-TMFVA1-00576','ESC-TMFVA1-00746','ESC-TMFVA1-01046','ESC-TMFVA1-01092','ESC-TMCPE-00530','ESC-TMCP1-00575','ESC-TMCP2-00576','ESC-TMFVA065-150','ESC-TMFVA145-150','ESC-TMFVS060-150','ESC-TMFVS145-150','ESC-TMCP1-00576','ESC-AA00T6000','ESC-AA03X0000','ESC-AA046J000','ESC-SBESDY-2XL','ESC-SBESDY-3XL','ESC-SBESDY-4XL','ESC-SBESDY-L','ESC-SBESDY-M','ESC-SBESDY-XL','ESC-SBESDBP-2XL','ESC-SBESDBP-3XL','ESC-SBESDBP-L','ESC-SBESDBP-M','ESC-SBESDBP-S','ESC-SBESDBP-XL','ESC-SBESDLB-2XL','ESC-SBESDLB-3XL','ESC-SBESDLB-4XL','ESC-SBESDLB-5XL','ESC-SBESDLB-L','ESC-SBESDLB-M','ESC-SBESDLB-S','ESC-SBESDLB-XL','ESC-SBESDDB-2XL','ESC-SBESDDB-3XL','ESC-SBESDDB-4XL','ESC-SBESDDB-5XL','ESC-SBESDDB-L','ESC-SBESDDB-M','ESC-SBESDDB-S','ESC-SBESDDB-XL','ESC-SBESDW-2XL','ESC-SBESDW-4XL','ESC-SBESDW-5XL','ESC-SBESDW-L','ESC-SBESDW-M','ESC-SBESDW-S','ESC-SBESDW-XL','ESC-SBESDP-2XL','ESC-SBESDP-3XL','ESC-SBESDP-4XL','ESC-SBESDP-5XL','ESC-SBESDP-L','ESC-SBESDP-M','ESC-SBESDP-S','ESC-SBESDP-XL','ESC-SBESDG-2XL','ESC-SBESDG-3XL','ESC-SBESDG-4XL','ESC-SBESDG-5XL','ESC-SBESDG-L','ESC-SBESDG-M','ESC-SBESDG-S','ESC-SBESDG-XL','ESC-T3M24