on conflict (corte_id, clave) do update set existencia=excluded.existencia;

on conflict (clave, mes) do update set venta=excluded.venta, traspasos=excluded.traspasos, dias_stock=excluded.dias_stock, dias=excluded.dias, existencia_fin=excluded.existencia_fin, entradas=excluded.entradas, dias_suficiente=excluded.dias_suficiente, venta_suficiente=excluded.venta_suficiente, traspasos_suficiente=excluded.traspasos_suficiente;

on conflict (oc_id, clave) do nothing;

on conflict (oc_id, clave) do nothing;

on conflict (oc_id, clave) do nothing;

